11	/// `/vault` — the epic's one lock screen, shown whenever
12	/// `VaultRepository.currentStatus` isn't `VaultStatus.unlocked`
13	/// (`core/navigation/app_router.dart`'s `_redirect`). Auto-triggers the OS
14	/// biometric prompt once in [initState]; a successful
15	/// [VaultRepository.authenticate] call flips `currentStatus` to `unlocked`,
16	/// which — via `statusStream`/`refreshListenable` — re-runs the redirect and
17	/// navigates away from here on its own, so this widget never navigates
18	/// imperatively itself.
19	///
20	/// Story 2.2: every biometric failure (decline/cancel/any OS lockout — the
21	/// generic `authenticate()` catches already cover it, spec-2-2) falls
22	/// through to a real [PinKeypad] + error band, never a second biometric
23	/// "Tentar novamente" affordance (AC2). The "Usar PIN" ghost link reaches
24	/// the same keypad directly, with no error band, before any biometric
25	/// failure has happened. [VaultRepository.submitPin]'s own success emits
26	/// `VaultStatus.unlocked`, same as [VaultRepository.authenticate] — this
27	/// widget navigates away on that exactly the same way, with no branch for
28	/// "which path unlocked it".
29	class VaultLockScreen extends StatefulWidget {
30	  const VaultLockScreen({required this.vaultRepository, super.key});
31	
32	  final VaultRepository vaultRepository;
33	
34	  @override
35	  State<VaultLockScreen> createState() => _VaultLockScreenState();
36	}
37	
38	class _VaultLockScreenState extends State<VaultLockScreen> {
39	  static const _biometricFailureMessage =
40	      'Não foi possível reconhecer — digite seu PIN';
41	
42	  /// No specific copy is given anywhere in `docs/input/` for a PIN
43	  /// mismatch (the I/O matrix only specifies the `Failure` returned) —
44	  /// decided here (Design Notes), mirroring the biometric failure band's
45	  /// own tone.
46	  static const _pinMismatchMessage = 'PIN incorreto. Tente novamente.';
47	
48	  /// No specific copy is given anywhere in `docs/input/` for a
49	  /// `submitPin` call that never resolves (decided here, Design Notes) —
50	  /// review finding: without a bound, a hung secure-storage channel call
51	  /// would leave [_submittingPin] stuck `true` forever, permanently
52	  /// blocking every future attempt and contradicting the spec's own
53	  /// "never a dead end" boundary.
54	  static const _submitTimeoutMessage =
55	      'Não foi possível verificar o PIN. Tente novamente.';
56	
57	  static const _submitPinTimeout = Duration(seconds: 10);
58	
59	  bool _showPinKeypad = false;
60	  String? _errorMessage;
61	
62	  /// Re-entrancy guard for [_submitPin], also passed to [PinKeypad] as
63	  /// `enabled: !_submittingPin` — [PinKeypad] clears its own buffer and
64	  /// accepts new taps immediately after calling `onSubmit`, before the
65	  /// awaited [VaultRepository.submitPin] below resolves, so a fast second
66	  /// 4-digit entry could otherwise be accepted and then silently dropped
67	  /// here with no feedback; gating the keypad itself means it's never
68	  /// accepted in the first place.
69	  bool _submittingPin = false;
70	
71	  @override
72	  void initState() {
73	    super.initState();
74	    _attemptAuthenticate();
75	  }
76	
77	  Future<void> _attemptAuthenticate() async {
78	    final result = await widget.vaultRepository.authenticate();
79	    if (!mounted) {
80	      return;
81	    }
82	
83	    // On success, `currentStatus` is already `unlocked` and the router's
84	    // own `refreshListenable` will navigate away from `/vault` on its own —
85	    // this widget has nothing further to do (and may already be in the
86	    // process of being disposed by the time that happens).
87	    var shouldAnnounceFailure = false;
88	    result.match(
89	      (_) {
90	        // If the user already reached the keypad manually (via "Usar
91	        // PIN") before this pending call resolved, this late failure must
92	        // never clobber whatever the keypad is currently showing — AC2's
93	        // "no second biometric-retry affordance" only concerns the
94	        // biometric view itself, which is no longer on screen.
95	        final alreadyOnKeypad = _showPinKeypad;
96	        shouldAnnounceFailure = !alreadyOnKeypad;
97	        if (!alreadyOnKeypad) {
98	          setState(() {
99	            _showPinKeypad = true;
100	            _errorMessage = _biometricFailureMessage;
101	          });
102	        }
103	      },
104	      (_) {},
105	    );
106	
107	    // `sendAnnouncement()` (see `_announce` below) is honored on both
108	    // Android and iOS — this app is iOS-only, where VoiceOver doesn't
109	    // reliably treat a live-region subtree update as an announcement on
110	    // its own, so the biometric->PIN transition is spoken explicitly
111	    // here rather than relying on any ambient live region.
112	    if (shouldAnnounceFailure && mounted) {
113	      await _announce(_biometricFailureMessage);
114	    }
115	  }
116	
117	  void _useManualPin() {
118	    setState(() {
119	      _showPinKeypad = true;
120	      _errorMessage = null;
121	    });
122	  }
123	
124	  Future<void> _submitPin(String pin) async {
125	    if (_submittingPin) {
126	      return;
127	    }
128	    setState(() => _submittingPin = true);
129	    try {
130	      final result = await widget.vaultRepository
131	          .submitPin(pin)
132	          .timeout(_submitPinTimeout);
133	      if (!mounted) {
134	        return;
135	      }
136	      if (result.isLeft()) {
137	        // Mismatch: stays locked, no attempt cap — the keypad itself has
138	        // already cleared its own buffer by the time this runs
139	        // (PinKeypad's own contract), so the user can simply try again.
140	        setState(() => _errorMessage = _pinMismatchMessage);
141	        await _announce(_pinMismatchMessage);
142	      }
143	      // On a match (first-use or later), `currentStatus` is already
144	      // `unlocked` and the router navigates away on its own, same as a
145	      // successful `authenticate()`.
146	    } on TimeoutException {
147	      if (!mounted) {
148	        return;
149	      }
150	      // Bounds the wait so a hung secure-storage call can never leave
151	      // `_submittingPin` stuck `true` forever — the `finally` below still
152	      // runs because this `await` has now actually completed (with a
153	      // thrown `TimeoutException`), same retryable outcome as a mismatch.
154	      setState(() => _errorMessage = _submitTimeoutMessage);
155	      await _announce(_submitTimeoutMessage);
156	    } finally {
157	      if (mounted) {
158	        setState(() => _submittingPin = false);
159	      } else {
160	        _submittingPin = false;
161	      }
162	    }
163	  }
164	
165	  Future<void> _announce(String message) async {
166	    if (!mounted) {
167	      return;
168	    }
169	    await SemanticsService.sendAnnouncement(
170	      View.of(context),
171	      message,
172	      TextDirection.ltr,
173	    );
174	  }
