182	          padding: DesignTokens.screenPadding,
183	          // No ambient `Semantics(liveRegion: true)` wrapper here — it
184	          // would re-trigger on every single digit tap inside `PinKeypad`
185	          // (its own `_ProgressDots` label changes each tap), not just the
186	          // two transitions that actually need announcing. Those two
187	          // (biometric failure, PIN mismatch) are already covered
188	          // explicitly and reliably by `_announce()` below.
189	          child: _showPinKeypad
190	              ? _PinView(
191	                  errorMessage: _errorMessage,
192	                  onSubmit: _submitPin,
193	                  enabled: !_submittingPin,
194	                )
195	              : _BiometricView(onUsePin: _useManualPin),
196	        ),
197	      ),
198	    );
